  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Kućica na Drini', 'Ikonický dřevěný domek na skalisku uprostřed řeky Driny, jeden z nejfotografovanějších motivů Srbska. Stojí tu od roku 1968 a přežil už několik povodní. Nejlepší pohled je přímo z nábřeží u Bajiny Bašty, pár minut od startu trasy.', 43.9858, 19.5247, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bajina_Ba%C5%A1ta,_ku%C4%87ica_na_steni_(_Ku%C4%87ica_na_Drini_).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bajina_Ba%C5%A1ta,_ku%C4%87ica_na_steni_(_Ku%C4%87ica_na_Drini_).jpg"}'::text[], 0),
    (v_route, 'Klášter Rača', 'Pravoslavný klášter ze 13. století, založený králem Dragutinem, ukrytý v zalesněném údolí říčky Rači. Za druhé světové války tu mniši schovávali vzácné Miroslavovo evangelium. Klidná zastávka hned na začátku stoupání do hor.', 43.9268, 19.5836, 'https://commons.wikimedia.org/wiki/Special:FilePath/Raca_Monastery.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Raca_Monastery.jpg"}'::text[], 1),
    (v_route, 'Mitrovac na Taře', 'Horská osada v srdci národního parku v nadmořské výšce kolem 1000 metrů, s návštěvnickým centrem NP Tara. Louky vonící borovicemi jsou ideální na krátkou pauzu a kávu z termosky. V okolí žije medvěd hnědý — odpadky rozhodně nenechávejte venku.', 43.9245, 19.4569, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mitrovac_na_Tari_-_panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mitrovac_na_Tari_-_panoramio.jpg"}'::text[], 2),
    (v_route, 'Jezero Zaovine', 'Rozvětvená přehradní nádrž s tyrkysovou vodou obklopená loukami a lesy, tišší sestra známějšího Perućacu. Úzká silnička kolem břehů patří k nejhezčím úsekům trasy. V zátokách se dá v létě i vykoupat.', 43.8905, 19.4102, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zaovine_Lake_(Jezero_Zaovine).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zaovine_Lake_(Jezero_Zaovine).jpg"}'::text[], 3),
    (v_route, 'Vyhlídka Banjska stena', 'Nejslavnější vyhlídka národního parku Tara — kolmý sráz vysoko nad kaňonem Driny a jezerem Perućac. Od parkoviště je to pohodlných deset minut pěšky lesem. Za jasného dne dohlédnete hluboko do Bosny na protějším břehu.', 43.9394, 19.4103, 'https://commons.wikimedia.org/wiki/Special:FilePath/Banjska_stena_-_Tara_02.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Banjska_stena_-_Tara_02.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vidikovac_Banjska_stena,_Nacionali_park_Tara.jpg"}'::text[], 4),
    (v_route, 'Přehrada Perućac', 'Mohutná hráz hydroelektrárny Bajina Bašta přehrazuje Drinu a vytváří 50 km dlouhé jezero v kaňonu. Sjezd serpentinami od Banjske steny k hladině je zábavný, ale pozor na štěrk v zatáčkách. U vody je několik plováren a bufetů na osvěžení.', 43.9635, 19.4831, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hidroelektrana_Bajina_Ba%C5%A1ta_006.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hidroelektrana_Bajina_Ba%C5%A1ta_006.jpg"}'::text[], 5);
