  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zlatibor – jezírko a centrum', 'Živé horské letovisko s promenádou kolem jezírka Kraljeve Vode. Ráno je ideální čas na kávu a doplnění zásob, než se dav turistů probudí. Odtud se rozjíždějí silnice do všech koutů pohoří.', 43.7286, 19.7004, 'https://commons.wikimedia.org/wiki/Special:FilePath/Park_jezero_zlatibor.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Park_jezero_zlatibor.jpg"}'::text[], 0),
    (v_route, 'Stopića jeskyně', 'Krápníková jeskyně s obřím vstupním portálem a proslulými travertinovými kaskádami, po kterých teče voda. Prohlídka po osvětlených lávkách zabere zhruba hodinu. Uvnitř je stabilních 8 stupňů — vezměte si vrstvu navíc.', 43.7047, 19.8085, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stopi%C4%87a_Pe%C4%87ina2.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stopi%C4%87a_Pe%C4%87ina2.jpg"}'::text[], 1),
    (v_route, 'Vodopád Gostilje', 'Dvacetimetrový vodopád na okraji stejnojmenné vesnice, k němuž vede krátká upravená stezka. Nejmohutnější je na jaře po tání; v horkých dnech osvěží vodní tříšť u tůně pod skálou. U parkoviště je stánek s domácí malinovou šťávou.', 43.6567, 19.8425, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zaledjeni_vodopad_Gostilje,_Zlatibor.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zaledjeni_vodopad_Gostilje,_Zlatibor.jpg"}'::text[], 2),
    (v_route, 'Skanzen Sirogojno', 'Muzeum Staro selo pod širým nebem — kompletní zlatiborská vesnice z 19. století s roubenkami, mlýnem i hospodou. Vesnice je zároveň proslulá ručně pletenými svetry. Prohlídka příjemně protáhne nohy po hodině v sedle.', 43.6939, 19.8244, 'https://commons.wikimedia.org/wiki/Special:FilePath/Staro_Selo_-_Sirogojno5.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Staro_Selo_-_Sirogojno5.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sirogojno.jpg"}'::text[], 3),
    (v_route, 'Šarganská osmička', 'Legendární úzkokolejka, která stoupá do kopců smyčkou ve tvaru osmičky přes 22 tunelů a 5 mostů. Nostalgický vlak Ćira jezdí několikrát denně z nádraží Mokra Gora — jízdenku kupte předem, v sezoně bývá plno. Výlet vlakem trvá zhruba dvě a půl hodiny.', 43.7908, 19.5033, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sargan_Eight_-_Golubici_station.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sargan_Eight_-_Golubici_station.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/JZ-83-173_sarganska1.jpg"}'::text[], 4),
    (v_route, 'Drvengrad', 'Dřevěné etno-městečko, které si režisér Emir Kusturica postavil na kopci Mećavnik nad Mokrou Gorou. Ulice pojmenované po filmařích, kino, galerie i vynikající restaurace. Z hradeb je krásný výhled na celé údolí a trať osmičky.', 43.7953, 19.5124, 'https://commons.wikimedia.org/wiki/Special:FilePath/Drvengrad_-_panorama.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Drvengrad_-_panorama.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Mokra_Gora,_Drvengrad.JPG"}'::text[], 5),
    (v_route, 'Restaurace: El Paso City (Zlatibor)', 'Westernové městečko s výborně hodnocenou restaurací kousek od centra Zlatiboru — grilované maso, telecí pod sačem a domácí chléb z pece. Ideální tečka za okruhem, večer tu bývá živá hudba. Velké parkoviště přímo u vjezdu.', 43.7350, 19.6990, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zlatiborsko_jezero_-_panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zlatiborsko_jezero_-_panoramio.jpg"}'::text[], 6);
