  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Vyhlídka Molitva', 'Nejslavnější pohled na meandry Uvce — řeka se pod vámi kroutí v dokonalých smyčkách mezi vápencovými stěnami. Z parkoviště vede k okraji srázu krátká pěšina. Držte se dál od hrany, zábradlí je jen místy.', 43.3178, 19.9114, 'https://commons.wikimedia.org/wiki/Special:FilePath/Meandri_Uvca_%E2%80%93_vidikovac_Molitva.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Meandri_Uvca_%E2%80%93_vidikovac_Molitva.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Meandri_Uvca.jpg"}'::text[], 0),
    (v_route, 'Rezervace Uvac – supi bělohlaví', 'Speciální přírodní rezervace chrání kolonii supů bělohlavých, kterých tu žije několik stovek. Nejlépe je pozorujete dopoledne, když nad kaňonem chytají termiku. Z přístaviště pod vyhlídkou vyplouvají i vyhlídkové čluny k jeskyni Ledena pećina.', 43.3300, 19.8850, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rezervat_prirode_Uvac,_Beloglavi_sup_02.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rezervat_prirode_Uvac,_Beloglavi_sup_02.jpg"}'::text[], 1),
    (v_route, 'Zlatarské jezero', 'Protáhlé přehradní jezero pod horou Zlatar, lemované chatami a plážemi. Silnice po jeho východním břehu nabízí sérii plynulých zatáček s výhledy na hladinu. Dobré místo na koupání i rychlý oběd u vody.', 43.4310, 19.7930, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zlatarsko_jezero_-_panoramio_(1).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zlatarsko_jezero_-_panoramio_(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kanjon_Uvca,_Zlatarsko_jezero,_Specijalni_rezervat_prirode_Uvac.JPG"}'::text[], 2),
    (v_route, 'Klášter Mileševa', 'Klášter z roku 1234, pohřebiště krále Vladislava a domov Bílého anděla — fresky, která je považována za jedno z vrcholných děl evropského středověku. Areál leží v tichém údolí kousek od Prijepolje. Vstup je zdarma, vhodné je zakrýt ramena a kolena.', 43.3866, 19.6606, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mileseva_Monastery_2.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mileseva_Monastery_2.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Beli_andjeo2.jpg"}'::text[], 3),
    (v_route, 'Prijepolje – Sahat kula', 'Městečko na soutoku Lima a Mileševky s orientální hodinovou věží ze 17. století. Směs pravoslavné a osmanské architektury dodává centru zvláštní atmosféru pomezí. Na korzu u řeky se dobře doplňuje kofein.', 43.3387, 19.6494, 'https://commons.wikimedia.org/wiki/Special:FilePath/Prijepolje_Sahat_Kula.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Prijepolje_Sahat_Kula.JPG"}'::text[], 4),
    (v_route, 'Přehrada Kokin Brod', 'Hráz na Uvci vzdouvá Radoinjské jezero se zelenkavou vodou obklopené borovými lesy. Silnice vede přímo po koruně hráze — kratičká, ale efektní pasáž. Poslední fotozastávka před návratem do Nove Varoše.', 43.4930, 19.7370, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nova_Varos_Kokin_Brod_uvac_river_Radoinjsko_Lake_IMG_9943.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nova_Varos_Kokin_Brod_uvac_river_Radoinjsko_Lake_IMG_9943.JPG"}'::text[], 5);
  insert into public.routes
