  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Petrovaradinská pevnost', 'Gibraltar na Dunaji — jedna z největších barokních pevností Evropy s proslulou hodinovou věží, jejíž velká ručička ukazuje hodiny, aby ji viděli lodníci z řeky. Z hradeb je nejlepší panorama Nového Sadu. Každý červenec pevnost hostí festival EXIT.', 45.2526, 19.8620, 'https://commons.wikimedia.org/wiki/Special:FilePath/Petrovaradin_Fortress,_Novi_Sad,_Serbia_14.09.2016.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Petrovaradin_Fortress,_Novi_Sad,_Serbia_14.09.2016.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Varadin_bridge_and_Novi_Sad_from_Petrovaradin_Fortress_4.jpg"}'::text[], 0),
    (v_route, 'Sremski Karlovci', 'Barokní městečko, které bývalo duchovním centrem srbského národa — katedrála, patriarchát, nejstarší srbské gymnázium a všude kolem vinné sklepy. Náměstí s kašnou Čtyři lvi je jako kulisa z filmu. Ochutnejte místní kuglof a nakupte bermet na doma.', 45.2029, 19.9335, 'https://commons.wikimedia.org/wiki/Special:FilePath/SREMSKI_KARLOVCI_Sveti_Nikola.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/SREMSKI_KARLOVCI_Sveti_Nikola.JPG"}'::text[], 1),
    (v_route, 'Restaurace: Dunav (Sremski Karlovci)', 'Tradiční, výborně hodnocená restaurace přímo na hlavním náměstí — sremské speciality, říční ryby a domácí štrúdl. V létě se sedí na zahrádce pod platany. Ideální oběd v půlce okruhu.', 45.2036, 19.9331, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sremski_Karlovci,_Kapela_Mira.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sremski_Karlovci,_Kapela_Mira.jpg"}'::text[], 2),
    (v_route, 'Klášter Krušedol', 'Nejvýznamnější z fruškogorských klášterů, založený počátkem 16. století, pohřebiště srbských despotů i krále Milana Obrenoviće. Červenobílý kostel obklopuje udržovaná zahrada. Klidné místo, kde provoz utichne na dohled od brány.', 45.1198, 19.9384, 'https://commons.wikimedia.org/wiki/Special:FilePath/Krusedol_Monastery,_Fruska_Gora,_Serbia.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Krusedol_Monastery,_Fruska_Gora,_Serbia.JPG"}'::text[], 3),
    (v_route, 'Klášter Novo Hopovo', 'Klášter s elegantním kostelem podle vzoru athoských staveb, ukrytý pod jižními svahy Fruške Gory u Irigu. Působil zde i osvícenec Dositej Obradović. Zastávka na pár minut ticha před stoupáním na hřeben.', 45.1178, 19.8547, 'https://commons.wikimedia.org/wiki/Special:FilePath/Novo_Hopovo_monastery.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Novo_Hopovo_monastery.jpg"}'::text[], 4),
    (v_route, 'Iriški venac – památník Sloboda', 'Sedlo na hřebeni Fruške Gory s monumentálním partyzánským památníkem Sloboda a televizní věží. Kříží se tu všechny cesty přes národní park, v lese jsou stánky s medem a klobásami. Odtud už se jen klesá zpátky k Dunaji.', 45.1554, 19.8492, 'https://commons.wikimedia.org/wiki/Special:FilePath/Iri%C5%A1ki_venac,_spomenik_Sloboda_001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Iri%C5%A1ki_venac,_spomenik_Sloboda_001.jpg"}'::text[], 5),
    (v_route, 'Ledinské jezero', 'Zatopený lom nad vesnicí Ledinci s průzračnou zelenou vodou pod bílými stěnami. V létě oblíbené koupaliště místních, mimo sezonu úplně prázdné. Krátká odbočka z hlavní silnice po zpevněné cestě.', 45.2018, 19.7684, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ledinacko_jezero,_Fruska_Gora.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ledinacko_jezero,_Fruska_Gora.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Jošanička Banja', 'Malé lázně s jedněmi z nejteplejších pramenů v Srbsku — voda tu vyvěrá s teplotou kolem 78 stupňů. Rodiště legendární hrdinky první světové války Milunky Savić, která tu má památník. Poslední civilizace před dlouhým stoupáním na hřeben.', 43.3894, 20.7561, 'https://commons.wikimedia.org/wiki/Special:FilePath/Banja_jo%C5%A1anica_-_panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Banja_jo%C5%A1anica_-_panoramio.jpg"}'::text[], 0),
    (v_route, 'Jankove bare', 'Rozlehlé horské rašeliniště a louky v národním parku, chráněná rezervace s dřevěnou vyhlídkou. Kontrast tichých mokřadů a smrkových lesů pár kilometrů od rušného střediska. Krátká odbočka ze silnice, ideální na protažení nohou.', 43.2547, 20.7690, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kopaonik_jankove_bare.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kopaonik_jankove_bare.jpg"}'::text[], 1),
    (v_route, 'Kopaonik – středisko', 'Největší horské středisko Srbska v 1770 metrech. V létě jezdí kabinová lanovka, funguje tu spousta restaurací a stánků — dobré místo na oběd s výhledem na sjezdovky zarostlé borůvčím. Benzinka je až dole v údolí, nahoře nedotankujete.', 43.2856, 20.8122, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDi%C4%8Dara_Kopaonik.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDi%C4%8Dara_Kopaonik.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kopaonik_zima.jpg"}'::text[], 2),
    (v_route, 'Pančićův vrch', 'Nejvyšší bod Kopaoniku (2017 m) s mauzoleem botanika Josifa Pančiće a radarovou kopulí. Za jasného počasí dohlédnete až na Prokletije. K vrcholu se dá vyjet lanovkou nebo dojít po hřebenové stezce; nahoře fouká vždy, vezměte si nákrčník.', 43.2692, 20.8256, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kopaonik_Pancicev-vrh.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kopaonik_Pancicev-vrh.JPG"}'::text[], 3),
    (v_route, 'Bele stene', 'Bílé vápencové skalní věže vystupující z lesů na východním okraji národního parku. Vyhlídka na údolí Rasiny a začátek dlouhého sjezdu do Brzeće. Fotogenické hlavně v nízkém večerním slunci.', 43.2790, 20.7930, 'https://commons.wikimedia.org/wiki/Special:FilePath/NP_Kopaonik_(NP02)_-_Bele_Stene_01.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/NP_Kopaonik_(NP02)_-_Bele_Stene_01.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Banja Koviljača', 'Nejstarší srbské lázně s nádherným parkem, secesními vilami a honosným Kur-salonem z dob království. Sirné a železité prameny tu léčí už dvě století. Příjemné místo na ranní kávu před vyjetím podél Driny.', 44.5171, 19.1571, 'https://commons.wikimedia.org/wiki/Special:FilePath/Park_Banja_Koviljaca.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Park_Banja_Koviljaca.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Fountain_in_Banja_Koviljaca.JPG"}'::text[], 0),
    (v_route, 'Tršić – rodiště Vuka Karadžiće', 'Upravená etno-vesnice s roubenkou, v níž se roku 1787 narodil reformátor srbského jazyka Vuk Stefanović Karadžić. Kolem památníku voní lipová alej, fungují tu dílny starých řemesel a stánky s domácími produkty. Prohlídka zabere půl hodinky.', 44.4749, 19.2438, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rodna_ku%C4%87a_Vuka_Stefanovi%C4%87a_Karad%C5%BEi%C4%87a,_Tr%C5%A1i%C4%87,_Srbija.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rodna_ku%C4%87a_Vuka_Stefanovi%C4%87a_Karad%C5%BEi%C4%87a,_Tr%C5%A1i%C4%87,_Srbija.jpg"}'::text[], 1),
    (v_route, 'Klášter Tronoša', 'Klášter ze 14. století schovaný v lesích nad Tršićem, kde se malý Vuk Karadžić učil číst a psát. Známý je obřími vyřezávanými svícemi, které se zapalují o Velikonocích. Přístup po úzké, ale asfaltované cestě údolím.', 44.4479, 19.2793, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trono%C5%A1a_monastery.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trono%C5%A1a_monastery.jpg"}'::text[], 2),
    (v_route, 'Zvornické jezero', 'Přehradní jezero na Drině mezi Malým Zvornikem a Zvornikem, sevřené strmými svahy. Silnice kopíruje břeh a nabízí dlouhé plynulé oblouky nad vodou. Na srbské straně je několik vyhlídkových odpočívadel s grilem.', 44.3735, 19.1198, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zvorni%C4%8Dko_jezero,_Zvornik.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zvorni%C4%8Dko_jezero,_Zvornik.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zvornik_Drina_Dam.JPG"}'::text[], 3),
    (v_route, 'Mačkov kamen', 'Památník a kostnice na hoře Jagodnja připomínající jednu z nejkrvavějších bitev srbské armády v roce 1914. Vede sem prázdná horská silnice s výhledy přes celé údolí Driny do Bosny. Pieta i panorama v jednom — vrchol této trasy.', 44.3333, 19.4000, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ma%C4%8Dkov_kamen,_kosturnica,_Ljubovija_03.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ma%C4%8Dkov_kamen,_kosturnica,_Ljubovija_03.JPG"}'::text[], 4);
