  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Klášter Žiča', 'Sytě červený klášter založený svatým Sávou roku 1208, korunovační chrám sedmi srbských králů — pro každého prý byla proražena nová brána. Leží jen pár kilometrů za Kraljevem v zeleni sadů. Otevřeno denně, vstup volný.', 43.6959, 20.6459, 'https://commons.wikimedia.org/wiki/Special:FilePath/Manastir_%C5%BDi%C4%8Da,_Kraljevo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Manastir_%C5%BDi%C4%8Da,_Kraljevo.jpg"}'::text[], 0),
    (v_route, 'Soutěska Ibaru', 'Sevřené údolí, kterým se řeka Ibar prodírá mezi Kraljevem a Raškou. Silnice kopíruje každý záhyb zelené řeky — jedna zatáčka střídá druhou. V květnu svahy rozkvétají šeříky, odtud přezdívka údolí jorgovanů.', 43.6500, 20.6250, 'https://commons.wikimedia.org/wiki/Special:FilePath/Reka_Ibar_02.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Reka_Ibar_02.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Reka_Ibar_Kraljevo_01.jpg"}'::text[], 1),
    (v_route, 'Pevnost Maglič', 'Středověký hrad na skalním ostrohu, který řeka Ibar obtéká ze tří stran — jedna z nejfotogeničtějších zřícenin Srbska. Nahoru vede strmá pěší stezka s visutou lávkou přes řeku, výstup zabere asi 25 minut. Motorku nechte na odpočívadle u silnice.', 43.6011, 20.5911, 'https://commons.wikimedia.org/wiki/Special:FilePath/Maglic-7k.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Maglic-7k.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/MAGLIC_-_main_tower.JPG"}'::text[], 2),
    (v_route, 'Klášter Studenica', 'Nejvýznamnější srbský klášter, zapsaný na seznamu UNESCO — kostel z bílého mramoru ukrývá fresky, které ovlivnily celé byzantské umění. Založil jej roku 1190 Stefan Nemanja, zakladatel srbského státu. Ticho za hradbami stojí za celou cestu.', 43.4863, 20.5316, 'https://commons.wikimedia.org/wiki/Special:FilePath/Manastir_Studenica_-_The_Studenica_Monastery.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Manastir_Studenica_-_The_Studenica_Monastery.jpg"}'::text[], 3),
    (v_route, 'Kraljevo – pomník krále Milutina', 'Královské město, jehož znak nese sedm korun podle sedmi panovníků korunovaných v Žiče. Na okružním náměstí stojí pomník krále Milutina a kolem něj kavárny na závěrečné posezení. Dobré místo na večeři po dni v sedle.', 43.7239, 20.6875, 'https://commons.wikimedia.org/wiki/Special:FilePath/Milutin,_Kraljevo_01.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Milutin,_Kraljevo_01.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Nišská pevnost', 'Rozlehlá osmanská pevnost z 18. století na břehu Nišavy, postavená na základech římského Naissu — rodiště císaře Konstantina. Uvnitř hradeb jsou kavárny, letní scéna a stín pod stoletými stromy. Motorku zaparkujete přímo u Istanbulské brány.', 43.3269, 21.8934, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ni%C5%A1_Fortress,_Ni%C5%A1,_Serbia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ni%C5%A1_Fortress,_Ni%C5%A1,_Serbia.jpg"}'::text[], 0),
    (v_route, 'Restaurace: Stara Srbija (Niš)', 'Proslulá kafana v uličce Kazandžijsko sokače, poslední dochované řemeslnické čtvrti Niše. Jižanská kuchyně v nejlepší formě — pljeskavice, punjene paprike a domácí rakije. Zajděte sem na vydatnou snídani nebo na večeři po návratu.', 43.3187, 21.8946, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kazandzijsko_Nis.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kazandzijsko_Nis.JPG"}'::text[], 1),
    (v_route, 'Prokuplje – Hisar', 'Návrší Hisar nad městem Prokuplje se zbytky středověké pevnosti a byzantské baziliky. Krátká odbočka s pěkným rozhledem na údolí Toplice, kterým pojedete dál na západ. Dole ve městě je poslední větší benzinka před horami.', 43.2306, 21.5861, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hisar_Fortress_in_Prokuplje_02.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hisar_Fortress_in_Prokuplje_02.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Prokuplje,_panorama_02.jpg"}'::text[], 2),
    (v_route, 'Đavolja varoš', 'Ďáblovo město — 202 hliněných věží až 15 metrů vysokých, každá s kamennou čepicí, vzniklých erozí sopečných hornin. Okolní prameny mají extrémně kyselou, rudě zbarvenou vodu. Od parkoviště vede k útvarům okruh po dřevěných lávkách, počítejte s hodinou chůze.', 42.9940, 21.4070, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C4%90avolja_Varo%C5%A1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C4%90avolja_Varo%C5%A1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Djavolja_varos_3.jpg"}'::text[], 3),
    (v_route, 'Ćele kula', 'Věž z lebek — memento z roku 1809, kdy osmanský paša nechal do věže zazdít lebky padlých srbských povstalců od Čegru. Z původních 952 lebek jich zbývá 58, dnes chráněných kaplí. Jedno z nejsilnějších míst Srbska, zastavte se tu na zpáteční cestě.', 43.3122, 21.9235, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nis_Cele_Kula.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nis_Cele_Kula.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Cele_kula_spolja.jpg"}'::text[], 4);
