  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Vršac – centrum', 'Vinařská metropole Banátu s barokní radnicí, farmaceutickým muzeem v nejstarší lékárně a katedrálou svatého Gerharda. Kolem města se rozkládají vinice už od římských dob. Kavárny na pěší zóně jsou ideální na start dne.', 45.1180, 21.2990, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vr%C5%A1ac-_gradska_ku%C4%87a.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vr%C5%A1ac-_gradska_ku%C4%87a.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vr%C5%A1ac_sa_Brega,_no%C4%87u.jpg"}'::text[], 0),
    (v_route, 'Vršacká věž', 'Středověká strážní věž z 15. století na vrcholu Vršackého bregu, přístupná krátkými serpentinami nad městem. Z ochozu přehlédnete vinice, celý Banát a za dobré viditelnosti i rumunské Karpaty. Nahoře skoro vždy fouká — ideální osvěžení v letním dni.', 45.1281, 21.3223, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vr%C5%A1a%C4%8Dka_kula_posle_obnove1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vr%C5%A1a%C4%8Dka_kula_posle_obnove1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vr%C5%A1a%C4%8Dka_kula_posle_obnove2.jpg"}'::text[], 1),
    (v_route, 'Klášter Mesić', 'Pravoslavný klášter ze 15. století schovaný v tichém údolí Vršackých hor u rumunské hranice. Kolem vede klidná silnička vinicemi a sady. Pěkná krátká zastávka mimo hlavní tahy.', 45.0819, 21.3897, 'https://commons.wikimedia.org/wiki/Special:FilePath/Manastir_Mesic.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Manastir_Mesic.JPG"}'::text[], 2),
    (v_route, 'Jezera u Bele Crkvy', 'Soustava sedmi jezer v bývalých štěrkovnách s nejčistší vodou pro koupání v Srbsku. Písčité pláže, kempy a bufety podél břehů — v létě živo, mimo sezonu klid. Hlavní jezero je hned u silnice, zastávka na vykoupání se přímo nabízí.', 44.8975, 21.4169, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bela_Crkva_lakes_-_morning.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bela_Crkva_lakes_-_morning.jpg"}'::text[], 3),
    (v_route, 'Deliblatská peščara', 'Evropská Sahara — 300 km² zvlněných písečných dun navátých v době ledové, dnes chráněná rezervace se stepní flórou, vlky a orly královskými. Silnice přes peščaru u výletiště Čardak se vlní mezi borovicemi jako horská cesta v rovině. Písek umí navát i na asfalt, v zatáčkách zpomalte.', 44.9210, 21.0930, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hills_of_Deliblatska_pescara,_Serbia.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hills_of_Deliblatska_pescara,_Serbia.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Deliblatska_pe%C5%A1%C4%8Dara_i_drvo.jpg"}'::text[], 4);
