  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Sokobanja', 'Nejstarší srbské vzdušné lázně s osmanským hammámem, pěší zónou plnou kaváren a horským vzduchem, který sem jezdil dýchat i nobelovec Ivo Andrić. Ráno na promenádě koupíte burek a čerstvý bylinkový čaj z Rtnje. Odtud se vyráží do kotliny pod pyramidu.', 43.6415, 21.8720, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sokobanja_view.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sokobanja_view.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sokobanja_2015_pesacka_zona.jpg"}'::text[], 0),
    (v_route, 'Hora Rtanj', 'Dokonale symetrická vápencová pyramida vysoká 1565 metrů, o níž legendy tvrdí, že vyzařuje léčivou energii — konspirační teorie sem roku 2012 přivedly davy čekající na konec světa. Silnice obkružuje horu a nabízí ji stále v jiném úhlu. Na úpatí rostou proslulé bylinky na rtanjský čaj.', 43.7200, 21.9100, 'https://commons.wikimedia.org/wiki/Special:FilePath/Planina_Rtanj.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Planina_Rtanj.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Piramida_Rtanj.jpg"}'::text[], 1),
    (v_route, 'Boljevac', 'Klidné městečko pod severním svahem Rtnje, odkud je na pyramidu nejhezčí ucelený pohled. Dobré místo na doplnění paliva a rychlou kávu na náměstí. Odtud se stáčí na východ k římským památkám.', 43.8256, 21.9525, 'https://commons.wikimedia.org/wiki/Special:FilePath/Boljevac_sa_Rtnja1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Boljevac_sa_Rtnja1.jpg"}'::text[], 2),
    (v_route, 'Felix Romuliana', 'Opevněný palác, který si císař Galerius postavil na místě svého rodiště a pojmenoval po matce Romule — památka UNESCO s mohutnými věžemi, mozaikami a chrámy z přelomu 3. a 4. století. Areál u Gamzigradu se prochází volně, počítejte s hodinou. Na slunci tu není stín, helmu i bundu nechte u motorky.', 43.8994, 22.1858, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gamzigrad_-_Felix_Romuliana_(by_Pudelek)_2.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gamzigrad_-_Felix_Romuliana_(by_Pudelek)_2.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Feliks_Romulijana_u_predvecerje.JPG"}'::text[], 3),
    (v_route, 'Zaječar', 'Okresní město s příjemným náměstím osvobození a Národním muzeem, kde jsou vystaveny originály nálezů z Felix Romuliany včetně porfyrové hlavy císaře Galeria. Kraj je také domovem piva Zaječarsko. Poslední zastávka před návratem přes kopce do Sokobanje.', 43.9036, 22.2847, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wiki.Biseri_III_Trg_oslobo%C4%91enja_(Zaje%C4%8Dar)_655.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wiki.Biseri_III_Trg_oslobo%C4%91enja_(Zaje%C4%8Dar)_655.jpg"}'::text[], 4);
